
// Verdicts taken from nil-kill's Ruby implementation over every Sorbet
// signature in this workspace. The port has to agree with the code it
// replaces on real input, not just on cases chosen to illustrate the rules.
use super::*;

    #[test]
    fn every_corpus_type_gets_the_same_verdict_as_ruby() {
        let cases: &[(&str, bool)] = &[
            ("CapturedOutput", true),
            ("CohortContribution", true),
            ("CommandLimits", true),
            ("CommandResult", true),
            ("CommandRunner", true),
            ("ContributionAnalysis", true),
            ("Corpus", true),
            ("CounterfactualProvenance", true),
            ("CounterfactualRequest", true),
            ("CounterfactualResult", true),
            ("Coverage", true),
            ("EvidenceCompleteness", true),
            ("EvidenceGate", true),
            ("EvidenceReport", true),
            ("EvidenceScope", true),
            ("FieldTypes", true),
            ("FindingKind", true),
            ("Float", true),
            ("IO", true),
            ("Integer", true),
            ("MatrixCheck", true),
            ("OracleExecutionRequest", true),
            ("OracleExecutionResult", true),
            ("OracleFact", true),
            ("OracleFacts", true),
            ("OracleMutationKind", true),
            ("OracleMutationPlan", true),
            ("OracleRewriteAdapter", true),
            ("OracleSensitivity", true),
            ("OracleSensitivityAnalysis", true),
            ("Regexp", true),
            ("ReviewFindingKind", true),
            ("SourceSpan", true),
            ("StabilityAnalysis", true),
            ("String", true),
            ("SubsumptionAnalysis", true),
            ("T.nilable(CohortEvidenceVector)", true),
            ("T.nilable(CommandResult)", true),
            ("T.nilable(ContributionAnalysis)", true),
            ("T.nilable(CounterfactualProvenance)", true),
            ("T.nilable(CounterfactualResult)", true),
            ("T.nilable(EvidenceScope)", true),
            ("T.nilable(IO)", true),
            ("T.nilable(Integer)", true),
            ("T.nilable(OracleKind)", true),
            ("T.nilable(OracleMutationPlan)", true),
            ("T.nilable(OracleRewrite)", true),
            ("T.nilable(OracleSensitivityAnalysis)", true),
            ("T.nilable(Process::Status)", true),
            ("T.nilable(SourceSpan)", true),
            ("T.nilable(StabilityAnalysis)", true),
            ("T.nilable(String)", true),
            ("T.nilable(T::Array[Integer])", true),
            ("T.nilable(T::Array[String])", true),
            ("T.nilable(T::Boolean)", true),
            ("T.nilable(Thread)", true),
            ("T.nilable([Integer, Integer])", true),
            ("T.proc.params(archived_source_path: String, resolved_revision: String).returns(T.untyped)", false),
            ("T.proc.params(node: T.untyped).void", false),
            ("T.untyped", false),
            ("T::Array[EquivalentMutantGroup]", true),
            ("T::Array[EvidenceVector]", true),
            ("T::Array[FindingKind]", true),
            ("T::Array[FrontierRanking]", true),
            ("T::Array[IndexedKillSet]", true),
            ("T::Array[Integer]", true),
            ("T::Array[KillTrial]", true),
            ("T::Array[OracleFact]", true),
            ("T::Array[OracleMutationPlan]", true),
            ("T::Array[OracleRewrite]", true),
            ("T::Array[OracleTrial]", true),
            ("T::Array[RerunCandidate]", true),
            ("T::Array[ReviewFinding]", true),
            ("T::Array[String]", true),
            ("T::Array[SubsumptionRelation]", true),
            ("T::Array[T.untyped]", false),
            ("T::Array[T::Hash[String, String]]", true),
            ("T::Array[T::Hash[String, T.untyped]]", false),
            ("T::Array[TestContribution]", true),
            ("T::Boolean", true),
            ("T::Hash[String, Float]", true),
            ("T::Hash[String, Integer]", true),
            ("T::Hash[String, String]", true),
            ("T::Hash[String, T.untyped]", false),
            ("T::Hash[String, T::Array[String]]", true),
            ("T::Hash[String, T::Array[T::Boolean]]", true),
            ("T::Hash[String, T::Set[String]]", true),
            ("T::Hash[[String, String], T::Array[T::Boolean]]", true),
            ("T::Set[String]", true),
            ("TYPE", true),
            ("TestContribution", true),
            ("TestObservation", true),
            ("TestOutcome", true),
            ("TestResultParser", true),
            ("Thread", true),
            ("[String, OracleRewrite]", true),
            ("[String, String]", true),
            ("[T::Boolean, T.nilable(String)]", true),
            ("[T::Hash[[String, String], T::Array[T::Boolean]], T::Boolean]", true),
        ];
        let mut disagreed = Vec::new();
        for (type_text, expected) in cases {
            if strong_trace_type(type_text) != *expected {
                disagreed.push(*type_text);
            }
        }
        assert!(disagreed.is_empty(), "disagreed with Ruby on: {disagreed:?}");
    }

