        let mut disagreed = Vec::new();
        for (sig, expected_params, expected_return) in cases {
            let got: Vec<(String, String)> = param_entries(sig);
            let want: Vec<(String, String)> = expected_params
                .iter()
                .map(|(n, t)| (n.to_string(), t.to_string()))
                .collect();
            if got != want {
                disagreed.push(format!("params {sig}: {got:?} != {want:?}"));
            }
            if return_type(sig).unwrap_or("") != *expected_return {
                disagreed.push(format!("return {sig}"));
            }
        }
        assert!(disagreed.is_empty(), "{} disagreements: {:?}", disagreed.len(), disagreed);
